1// Reverse the list
2 void reverse_list(){
3   // If list is empty no nothing
4    if(head == nullptr) return;
5    
6   // Create a vector to store list data
7    vector<int> list_data;
8    
9   // Start from the head node
10    Node<T>* current = head;
11    
12   // Iterate through the vector
13    while(current != nullptr){
14     // Insert the node data into the vector
15      list_data.emplace_back(current->data);
16      
17      current = current->next;
18    }
19    // Reverse the vector
20    reverse(list_data.begin(), list_data.end());
21    
22    current = head;
23    for(int val: list_data){
24       // Change the value of current node
25       current->data = val;
26       
27       // Move to the next node
28       current = current->next;
29    }
30 }
